function searchableDocuments(){const memberDocs=accessMembers().flatMap(member=>member.documents.filter(document=>document.fileUrl).map(document=>({group:document.type,name:document.documentName||document.fileName||document.type,owner:member.name,fileUrl:document.fileUrl,fileName:document.fileName||'',search:`${member.name} ${document.type} ${document.documentName||''} ${document.number||''} ${document.fileName||''}`})));if(access.role==='child')return memberDocs;const propertyDocs=(state.properties||[]).flatMap(property=>(property.documents||[]).filter(document=>document.fileUrl).map(document=>({group:'House & Property',name:document.type,owner:property.title,fileUrl:document.fileUrl,fileName:document.fileName||'',search:`${property.title} ${document.type} ${document.fileName||''}`}))),vehicleDocs=(state.vehicles||[]).flatMap(vehicle=>[['RC Book',vehicle.fileUrl,vehicle.fileName],['Vehicle Insurance',vehicle.insuranceFileUrl,vehicle.insuranceFileName],['Pollution Under Check',vehicle.pucFileUrl,vehicle.pucFileName],['Challans',vehicle.challanFileUrl,vehicle.challanFileName],['Maintenance Service',vehicle.maintenanceFileUrl,vehicle.maintenanceFileName]].filter(([,url])=>url).map(([type,fileUrl,fileName])=>({group:'Vehicles',name:type,owner:vehicle.model,fileUrl,fileName:fileName||'',search:`${vehicle.model} ${vehicle.vehicleNumber||''} ${type} ${fileName||''}`})));return [...memberDocs,...propertyDocs,...vehicleDocs]}
function openDocumentSearch(){$('#modalContent').innerHTML=`<h2>Find a document</h2><p>Search by family member, record type, property, vehicle, or file name.</p><div class="form-grid"><label class="full">SEARCH<input id="documentQuery" autofocus placeholder="e.g. Aadhaar, Prativa, sale deed, RC book" oninput="queryDocuments()"></label></div><div id="documentSearchResults" class="category-list"><small class="no-docs">Enter a search term to retrieve a saved scan.</small></div>`;$('#modal').classList.add('show')}
function queryDocuments(){const query=($('#documentQuery')?.value||'').trim().toLowerCase(),box=$('#documentSearchResults');if(!box)return;if(!query){box.innerHTML='<small class="no-docs">Enter a search term to retrieve a saved scan.</small>';return}const matches=searchableDocuments().filter(document=>document.search.toLowerCase().includes(query));box.innerHTML=matches.map(document=>`<div class="identity-record"><div><b>${document.name}</b><small>${document.group} · ${document.owner}${document.fileName?' · '+document.fileName:''}</small></div><span class="record-actions"><a href="${document.fileUrl}" target="_blank">Open scan</a></span></div>`).join('')||'<small class="no-docs">No matching saved scans found.</small>'}
