function openAccessModal(){if(access.role!=='head'){alert('Only the Head of household can manage vault permissions.');return}const roles=[['head','Head of household'],['homemaker','Homemaker'],['child','Child']];$('#modalContent').innerHTML=`<h2>Family vault permissions</h2><p>Assign a role to each family member. Only the Head of household can make these changes.</p><form onsubmit="saveRoleAssignments(event)"><div class="role-assignment-list">${state.members.map(member=>`<label>${member.name}<select name="role-${member.id}">${roles.map(([value,label])=>`<option value="${value}" ${defaultVaultRole(member)===value?'selected':''}>${label}</option>`).join('')}</select></label>`).join('')}</div><button class="primary">Save permissions</button></form>`;$('#modal').classList.add('show')}
