function addSandukHero(){const art=$('#dashboardHero .hero-art');if(!art)return;art.innerHTML='<img src="/assets/sanduk-hero.png" alt="Traditional household sanduk with family records">';if(!$('#sandukHeroStyles')){const style=document.createElement('style');style.id='sandukHeroStyles';style.textContent='#dashboardHero .hero-art{background:#f5e6c9;overflow:hidden}#dashboardHero .hero-art img{width:100%;height:100%;object-fit:cover;object-position:center;display:block}';document.head.append(style)}}
