function renderIdentityMenu(){const box=document.querySelector('.identity-menu'),types=['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate'],identityLink=document.querySelector('nav a[href="#identification"]');if(identityLink){identityLink.innerHTML='<i>▣</i> Identity & Documents';identityLink.onclick=()=>setTimeout(showIdentityReadme,0)}if(box)box.style.display='none';let menu=document.querySelector('.identity-submenu'),toggle=document.querySelector('.identity-toggle');if(!menu&&identityLink){menu=document.createElement('div');menu.className='identity-submenu';identityLink.after(menu)}if(!toggle&&identityLink){toggle=document.createElement('button');toggle.className='identity-toggle';toggle.type='button';toggle.onclick=toggleIdentityMenu;Object.assign(toggle.style,{position:'absolute',left:'190px',top:'128px',border:'0',background:'transparent',color:'#355b4d',fontSize:'14px'});identityLink.parentElement.style.position='relative';identityLink.after(toggle)}if(!menu)return;menu.dataset.expanded=menu.dataset.expanded||'true';if(toggle)toggle.textContent=menu.dataset.expanded==='true'?'⌃':'⌄';Object.assign(menu.style,{display:menu.dataset.expanded==='true'?'flex':'none',flexDirection:'column',margin:'-2px 0 5px 29px',gap:'1px'});menu.innerHTML=types.map(type=>`<button onclick="openIdentityType('${type}',this)" style="border:0;text-align:left;padding:6px 8px;border-radius:6px;background:transparent;color:#355b4d;font:600 10px Manrope">${type}</button>`).join('')}
function renderResetButton(){let button=$('#resetData');if(!button){button=document.createElement('button');button.id='resetData';button.className='reset-data';button.textContent='Wipe all data';button.title='Delete all family records and uploaded scans';button.onclick=resetAllData}$('#dashboardStats')?.after(button)}
async function resetAllData(){if(!confirm('Wipe all data? This permanently deletes every family member, record, property, vehicle and uploaded scan.'))return;if(!confirm('This cannot be undone. Delete everything now?'))return;const button=$('#resetData');if(button){button.disabled=true;button.textContent='Wiping vault…'}try{const response=await fetch('/api/data/reset',{method:'POST',cache:'no-store'}),result=await response.json();if(!response.ok)throw new Error(result.error||'Could not wipe the data.');const remaining=result.data||{};if((remaining.members||[]).length||(remaining.properties||[]).length||(remaining.vehicles||[]).length)throw new Error('The vault still contains records.');localStorage.removeItem('hearthAccess');activePropertyId=undefined;alert(`Vault wiped: ${result.cleared.members} family members, ${result.cleared.documents} scanned documents, ${result.cleared.properties} properties and ${result.cleared.vehicles} vehicles removed.`);location.hash='dashboard';location.reload()}catch(error){alert(error.message||'Could not wipe the data. Please try again.');if(button){button.disabled=false;button.textContent='Wipe all data'}}}
async function renderPrivateAi(){let box=$('#privateAi');if(!box){box=document.createElement('section');box.id='privateAi';box.className='private-ai';$('#dashboardStats')?.after(box)}const status=await fetch('/api/ai/status').then(response=>response.json()).catch(()=>({configured:false}));box.innerHTML=`<div><p class="eyebrow">PRIVATE AI</p><h3>Ask Hearth</h3><p>${status.configured?'Searches your encrypted records using the local home-server model.':'Set up a local model on the home server to enable private document reasoning.'}</p></div><div class="private-ai-query"><input id="privateAiQuestion" ${status.configured?'':'disabled'} placeholder="Ask about a document, expiry, address or record" onkeydown="if(event.key==='Enter')askPrivateAi()"><button ${status.configured?'':'disabled'} onclick="askPrivateAi()">Ask</button></div><div id="privateAiAnswer">${status.indexedAt?'Vector index ready.':'No vector index created yet.'}</div>`;if(!$('#privateAiStyle')){const style=document.createElement('style');style.id='privateAiStyle';style.textContent='.private-ai{display:grid;grid-template-columns:1fr 1.2fr;gap:1.5rem;margin:1.4rem 0;padding:1.45rem;border:1px solid #c9c3ff;border-radius:18px;background:#f7f6ff}.private-ai h3{margin:.1rem 0 .45rem;color:#25205b}.private-ai p{margin:0;color:#575a72}.private-ai-query{display:flex;gap:.6rem;align-items:center}.private-ai-query input{flex:1;padding:.75rem;border:1px solid #bdb9e8;border-radius:9px;background:#fff}.private-ai-query button{padding:.75rem 1rem;border:0;border-radius:9px;background:#4338a8;color:#fff}.private-ai-query button:disabled{opacity:.5}.private-ai #privateAiAnswer{grid-column:1/-1;white-space:pre-wrap;color:#302f49}.private-ai .source{display:inline-block;margin:.45rem .45rem 0 0;padding:.25rem .5rem;border-radius:999px;background:#e7e4ff;font-size:.8rem}@media(max-width:700px){.private-ai{grid-template-columns:1fr}.private-ai #privateAiAnswer{grid-column:auto}}';document.head.append(style)}}
async function askPrivateAi(){const question=$('#privateAiQuestion')?.value.trim(),answer=$('#privateAiAnswer');if(!question||!answer)return;answer.textContent='Searching your private records locally…';const response=await fetch('/api/ai/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question})}),result=await response.json();if(!response.ok){answer.textContent=result.error||'Private AI is unavailable.';return}answer.innerHTML=`<b>Hearth</b><br>${result.answer.replace(/</g,'&lt;').replace(/>/g,'&gt;')}<br>${result.sources.map(source=>`<span class="source">[${source.citation}] ${source.type} · ${source.owner}</span>`).join('')}`}
