function showAchievementRecords(){const render=(type,id)=>{const records=accessMembers().flatMap(m=>m.documents.filter(d=>d.type===type).map(d=>({...d,member:m.name}))),box=$(id);if(!box)return;box.innerHTML=records.map(d=>`<div><span>${d.member}<small>${d.documentName||type}${d.documentDate?' · Year: '+d.documentDate:''}</small></span>${d.fileUrl?`<a href="${d.fileUrl}" target="_blank">${d.member.replace(/\s+/g,'')}_${type}</a>`:''}</div>`).join('')||`<small class="no-docs">No ${type.toLowerCase()} records added yet.</small>`};render('Sports','#sportsDocs');render('Extracurricular','#extracurricularDocs')}
