function groupEducationRecords(){const types=['Class 10','Class 12','Graduation','Post Graduation','PhD'],groups=accessMembers().map(m=>({member:m,docs:m.documents.filter(d=>types.includes(d.type))})).filter(group=>group.docs.length),box=$('#educationDocs');if(!box)return;box.innerHTML=groups.map(group=>`<section class="education-member"><h4>${group.member.name}</h4>${group.docs.map(d=>`<div class="identity-record"><div><b>${d.type}-${d.subtype||'Document'}</b><small>Year of Passing: ${d.documentDate||'Not added'}</small></div><span class="record-actions">${d.fileUrl?`<a href="${d.fileUrl}" target="_blank">${group.member.name.replace(/\s+/g,'')}-${d.type.replace(/\s+/g,'')}-${d.subtype||'Document'}</a>`:'<small>Scan not attached</small>'}<button onclick="openModal('editDoc','${group.member.id}','${d.id}')">Edit</button><button class="delete" onclick="deleteDoc('${group.member.id}','${d.id}')">Delete</button></span></div>`).join('')}</section>`).join('')||'<small class="no-docs">No education records added yet.</small>'}
function renameEducationRecordLabels(){const types=['Class 10','Class 12','Graduation','Post Graduation','PhD'],docs=state.members.flatMap(m=>m.documents.filter(d=>types.includes(d.type)).map(d=>({...d,member:m.name})));document.querySelectorAll('#educationDocs .identity-record b').forEach((label,index)=>{const d=docs[index];if(d)label.textContent=`${d.member}-${d.type}-${d.subtype||'Document'}`})}
function showMissingDobStatus(){const types=['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate'],docs=state.members.flatMap(m=>m.documents.map(d=>({...d}))).filter(d=>types.includes(d.type)).sort((a,b)=>types.indexOf(a.type)-types.indexOf(b.type));document.querySelectorAll('#identityDocs .identity-record > div > small').forEach((detail,i)=>{if(docs[i]&&!docs[i].documentDate)detail.textContent+=' · DOB: Not detected — Edit to add'})}
function moveScanLinks(){const types=['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate'],docs=state.members.flatMap(m=>m.documents.map(d=>({...d,member:m.name}))).filter(d=>types.includes(d.type)).sort((a,b)=>types.indexOf(a.type)-types.indexOf(b.type));document.querySelectorAll('#identityDocs .identity-record').forEach((record,i)=>{const scan=record.querySelector('.record-actions a'),label=record.querySelector('b'),doc=docs[i];if(scan&&label){const person=(doc.documentName||doc.member||'Document').replace(/\s+/g,'');const type=doc.type==='Aadhaar'?'Aadhar':doc.type.replace(/\s+/g,'');scan.textContent=`${person}_${type}`;label.after(scan)}})}
function addRereadButtons(){const types=['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate'],docs=state.members.flatMap(m=>m.documents.map(d=>({...d,memberId:m.id}))).filter(d=>types.includes(d.type)).sort((a,b)=>types.indexOf(a.type)-types.indexOf(b.type));document.querySelectorAll('#identityDocs .record-actions').forEach((actions,i)=>{const d=docs[i];if(!d?.fileUrl)return;const button=document.createElement('button');button.textContent='Re-read';button.onclick=()=>rereadDoc(d.memberId,d.id);actions.prepend(button)})}
async function rereadDoc(member,id){const r=await fetch(`/api/members/${member}/documents/${id}?action=ocr`,{method:'POST'});if(!r.ok){alert('Could not re-read this scan. You can update the address manually with Edit.');return}load()}
function applyDocumentView(){const records=['identification','education','finance','trackers','locations','health','property','vehicles'].map(id=>$('#'+id)).filter(Boolean),family=[$('#family'),$('#members')],dashboard=[$('#dashboardHero'),$('#dashboardStats'),$('#privateAi'),$('#resetData')].filter(Boolean),selected=location.hash.slice(1),areas=['family','identification','education','finance','trackers','locations','health','property','vehicles'];if(areas.includes(selected)){dashboard.forEach(el=>el.style.display='none');family.forEach(el=>el.style.display=selected==='family'?'':'none');records.forEach(el=>el.style.display=el.id===selected?'':'none');if(selected==='identification')showIdentityReadme();if(selected==='education')showAcademicReadme();if(selected==='finance')showFinanceReadme();return}dashboard.forEach(el=>el.style.display='');family.forEach(el=>el.style.display='none');records.forEach(el=>el.style.display='none')}
