function renderFinanceMenu(){const link=document.querySelector('nav a[href="#finance"]');if(!link)return;const nav=link.closest('nav'),sidebarBottom=$('.sidebar-bottom');if(nav)Object.assign(nav.style,{overflowY:'auto',minHeight:'0',paddingRight:'3px'});if(sidebarBottom)sidebarBottom.style.flexShrink='0';let menu=document.querySelector('.finance-submenu');if(!menu){menu=document.createElement('div');menu.className='finance-submenu';link.after(menu)}const button=type=>`<button onclick="setFinanceSection('${type}',this)" style="border:0;text-align:left;padding:6px 8px;border-radius:6px;background:transparent;color:#355b4d;font:600 10px Manrope">${type}</button>`;menu.dataset.expanded=menu.dataset.expanded||'true';link.innerHTML=`<i>◇</i> Finance <span onclick="event.preventDefault();event.stopPropagation();toggleFinanceMenu()" style="margin-left:auto;font-size:15px">${menu.dataset.expanded==='true'?'⌃':'⌄'}</span>`;link.onclick=()=>setTimeout(showFinanceReadme,0);Object.assign(menu.style,{display:menu.dataset.expanded==='true'?'flex':'none',flexDirection:'column',margin:'-2px 0 5px 29px',gap:'1px'});menu.innerHTML=financeTypes.map(button).join('')}
