function renderFinanceImportControls(){const title=$('#finance .section-title');if(!title)return;let controls=$('#financeImportControls');if(!controls){controls=document.createElement('div');controls.id='financeImportControls';title.after(controls)}controls.innerHTML=`<div class="section-readme"><h3>Import financial records</h3><p>Download the Excel template with every family member’s name, fill one row for each record, then upload it. Records are added to the matching Finance subsection.</p><span class="record-actions"><button class="textbutton" onclick="downloadFinanceTemplate()">↓ Download Excel template</button><label class="textbutton" style="cursor:pointer">↑ Upload filled template<input id="financeImportFile" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" style="display:none" onchange="uploadFinanceWorkbook(this)"></label></span></div>`}
