async function uploadFinanceWorkbook(input){const file=input.files?.[0];if(!file)return;const fileData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)}),response=await fetch('/api/finance/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileName:file.name,fileData})}),result=await response.json();if(!response.ok){alert(result.error||'The Finance workbook could not be imported.');input.value='';return}alert(`${result.imported} financial record${result.imported===1?'':'s'} imported.${result.skipped?.length?' '+result.skipped.length+' row(s) skipped.':''}`);load()}
