function toggleTrackerMenu(){const menu=document.querySelector('.tracker-submenu');if(!menu)return;menu.dataset.expanded=menu.dataset.expanded==='true'?'false':'true';renderTrackerMenu()}
function setTrackerSection(type,button){location.hash='trackers';const box=$('#trackers');if(box)box.querySelectorAll('.tracker-section').forEach(section=>section.style.display=section.querySelector('h3')?.textContent===type?'':'none');document.querySelectorAll('.tracker-submenu button').forEach(item=>item.style.background=item.textContent===type?'#dcecdf':'transparent');if(button)button.style.background='#dcecdf'}
function financeReadme(){let readme=$('#financeReadme'),intro=$('#finance .finance-intro');if(!readme&&intro){readme=document.createElement('div');readme.id='financeReadme';readme.className='section-readme';readme.innerHTML='<h3>How to use Financial Records</h3><p>Select an account type from the left menu to add or review records for a family member.</p><p>Banking accounts store bank name, account number, and Savings or Current type. Other sections keep PPF, EPF, NPS, Demat, Postoffice Savings, and insurance records organised separately.</p>';intro.after(readme)}return readme}
function showFinanceReadme(){const readme=financeReadme(),intro=$('#finance .finance-intro'),sections=$('#finance .finance-sections');if(readme)readme.style.display='';if(intro)intro.style.display='none';if(sections)sections.style.display='none';document.querySelectorAll('.finance-submenu button').forEach(button=>button.style.background='transparent')}
function setFinanceSection(type,button){const readme=$('#financeReadme'),intro=$('#finance .finance-intro'),sections=$('#finance .finance-sections');if(readme)readme.style.display='none';if(intro)intro.style.display='none';if(sections)sections.style.display='';document.querySelectorAll('.finance-section').forEach(section=>section.style.display=section.querySelector('h3')?.textContent===type?'':'none');document.querySelectorAll('.finance-submenu button').forEach(b=>b.style.background=b.textContent===type?'#dcecdf':'transparent');if(button)button.style.background='#dcecdf'}
function toggleAcademicMenu(){const menu=document.querySelector('.academic-submenu');if(!menu)return;const expanded=menu.dataset.expanded!=='true';menu.dataset.expanded=expanded?'true':'false';renderAcademicMenu()}
function academicReadme(){let readme=$('#academicReadme'),title=$('#education .section-title');if(!readme&&title){readme=document.createElement('div');readme.id='academicReadme';readme.className='section-readme';readme.innerHTML='<h3>How to use Academic &amp; Achievements</h3><p>Choose <b>Education</b>, <b>Sports</b>, or <b>Extracurricular</b> from the left menu. Education records are grouped under each family member so certificates and marksheets stay together.</p><p>Add a scan, check the captured details, and save it to keep achievements organised in one place.</p>';title.after(readme)}return readme}
function showAcademicReadme(){const readme=academicReadme();if(readme)readme.style.display='';document.querySelectorAll('#education > article').forEach(article=>article.style.display='none');document.querySelectorAll('.academic-submenu button').forEach(b=>b.style.background='transparent')}
function setAcademicSection(type,button){const readme=$('#academicReadme');if(readme)readme.style.display='none';document.querySelectorAll('#education > article').forEach(article=>article.style.display=article.querySelector('h3')?.textContent===type?'':'none');document.querySelectorAll('.academic-submenu button').forEach(b=>{const active=b.textContent===type;b.style.background=active?'#e5e2f3':'transparent'});if(button)button.style.background='#e5e2f3'}
function renderVehicleNav(){let link=document.querySelector('nav a[href="#vehicles"]');if(link)return;link=document.createElement('a');link.href='#vehicles';link.innerHTML='<i>▱</i> Vehicles';document.querySelector('nav').append(link)}
function renderLocationNav(){let link=document.querySelector('nav a[href="#locations"]');if(link)return;link=document.createElement('a');link.href='#locations';link.innerHTML='<i>⌖</i> Location Information';const familyLink=document.querySelector('nav a[href="#family"]');if(familyLink)familyLink.after(link);else document.querySelector('nav').append(link)}
function renderLocations(){let box=$('#locations');if(!box){box=document.createElement('section');box.id='locations';box.className='document-sections';$('#family').after(box)}const members=accessMembers();box.innerHTML=`<div class="section-title"><div><p class="eyebrow">LOCATION INFORMATION</p><h2>Family check-ins</h2></div></div><p class="finance-intro">Voluntary location updates shared within the household. This does not use automatic or background tracking.</p><div class="members">${members.map(member=>{const location=member.location||{};return `<article class="member"><div class="member-top"><span class="avatar">${initials(member.name)}</span><div><h3>${member.name}<small>${location.status||'No status shared'}</small></h3></div></div><div class="member-info"><span>LOCATION<b>${location.place||'Not shared'}</b></span><span>UPDATED<b>${location.updatedAt||'Not updated'}</b></span></div><button class="textbutton" style="margin-top:14px" onclick="openLocationModal('${member.id}')">Update check-in</button></article>`}).join('')||'<p class="property-empty">No family members available.</p>'}</div>`}
function openLocationModal(memberId){const member=state.members.find(item=>item.id===memberId),location=member?.location||{};$('#modalContent').innerHTML=`<h2>Update location check-in</h2><p>Share a voluntary current location with your household.</p><form onsubmit="saveLocationCheckin(event,'${memberId}')"><div class="form-grid"><label>LOCATION<input required name="place" value="${location.place||''}" placeholder="e.g. Office, School, Home"></label><label>STATUS<select name="status">${['Available','At home','At work / school','Travelling','Do not disturb'].map(status=>`<option ${location.status===status?'selected':''}>${status}</option>`).join('')}</select></label><label class="full">NOTE<input name="note" value="${location.note||''}" placeholder="Optional check-in note"></label></div><button class="primary">Share check-in</button></form>`;$('#modal').classList.add('show')}
async function saveLocationCheckin(e,memberId){e.preventDefault();const member=state.members.find(item=>item.id===memberId),location={...Object.fromEntries(new FormData(e.target)),updatedAt:new Date().toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})},response=await fetch(`/api/members/${memberId}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...member,location})});if(!response.ok){alert('The location check-in could not be saved.');return}closeModal();load()}
function renderVehicles(){const box=$('#vehiclesList'),vehicles=state.vehicles||[];if(!box)return;const doc=(url,label)=>url?`<a href="${url}" target="_blank">${label}</a>`:`<small>${label.replace(/_/g,' ')} not attached</small>`;box.innerHTML=vehicles.map(v=>{const label=v.model.replace(/\s+/g,'');return `<article class="vehicle-card"><span>▱</span><div><b>${v.model}</b><small>Vehicle number: ${v.vehicleNumber||'Not added'} · Registered: ${v.registrationDate||'Not added'}</small><small>Registration authority: ${v.registrationAuthority||'Not added'}${v.estimatedValue?' · Estimated value: '+formatAmount(amountValue(v.estimatedValue)):''}</small><span class="vehicle-documents">${doc(v.fileUrl,label+'_RCBook')}${doc(v.insuranceFileUrl,label+'_Insurance')}${doc(v.pucFileUrl,label+'_PUC')}${doc(v.challanFileUrl,label+'_Challans')}${doc(v.maintenanceFileUrl,label+'_Maintenance')}</span></div><span class="row-actions"><button onclick="openVehicleModal('${v.id}')">Edit</button><button class="delete" onclick="deleteVehicle('${v.id}')">Delete</button></span></article>`}).join('')||'<p class="property-empty">No vehicle records added yet.</p>'}
const financeTypes=['Banking accounts','Credit cards','Debit cards','Forex Cards','UPI','Fixed Deposits','PPF Account','EPF Account','NPS Account','Demat Account','Postoffice Savings','Insurance policies'];
const trackerTypes=['Expense Tracker','Loan & EMI Tracker','Net Worth Snapshot'];
const amountValue=value=>Number(String(value||'').replace(/[^0-9.-]/g,''))||0;
const formatAmount=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(value||0);
function financeDetail(record){if(record.type==='Expense Tracker')return `${record.category||'Uncategorized'} · ${formatAmount(amountValue(record.amount))}${record.expenseDate?' · '+record.expenseDate:''}${record.merchant?' · '+record.merchant:''}`;if(record.type==='EPF Account')return `UAN: ${record.uan||'Not added'}`;if(record.type==='Insurance policies')return `${record.policyName||'Policy name not added'} · Policy ID: ${record.policyId||'Not added'}${record.maturityDate?' · Maturity: '+record.maturityDate:''}`;if(record.type==='UPI')return `UPI ID: ${record.upiId||'Not added'}${record.provider?' · '+record.provider:''}${record.bankName?' · '+record.bankName:''}`;if(record.type==='Loan & EMI Tracker'||record.type==='Loans')return `${record.lender||record.bankName||'Lender not added'} · Loan account: ${record.loanNumber||record.accountNumber||'Not added'}${record.emiAmount?' · EMI: '+formatAmount(amountValue(record.emiAmount)):''}${record.emiDueDate?' · Due: '+record.emiDueDate:''}`;if(record.type==='Fixed Deposits')return `${record.bankName||'Bank name not added'} · FD number: ${record.accountNumber||'Not added'}${record.maturityDate?' · Maturity: '+record.maturityDate:''}`;if(record.type==='Credit cards'||record.type==='Debit cards'||record.type==='Forex Cards')return `${record.bankName||record.provider||'Provider not added'} · Card number: ${record.cardNumber||'Not added'}${record.cardNetwork?' · '+record.cardNetwork:''}${record.expiryDate?' · Expiry: '+record.expiryDate:''}`;return `${record.bankName||'Bank name not added'} · Account number: ${record.accountNumber||'Not added'}${record.accountType?' · '+record.accountType:''}`}
function netWorthSnapshot(){const propertyValue=(state.properties||[]).reduce((total,property)=>total+amountValue(property.estimatedValue),0),vehicleValue=(state.vehicles||[]).reduce((total,vehicle)=>total+amountValue(vehicle.estimatedValue),0),fixedDepositValue=accessMembers().flatMap(member=>member.finance||[]).filter(record=>record.type==='Fixed Deposits').reduce((total,record)=>total+amountValue(record.depositAmount),0),total=propertyValue+vehicleValue+fixedDepositValue;return `<article class="document-category tracker-section"><div class="category-head"><div><h3>Net Worth Snapshot</h3></div></div><p>Current estimate from recorded property, vehicle, and fixed-deposit values.</p><div class="category-list"><div class="identity-record"><div><b>${formatAmount(total)}</b><small>Property: ${formatAmount(propertyValue)} · Vehicles: ${formatAmount(vehicleValue)} · Fixed deposits: ${formatAmount(fixedDepositValue)}</small></div></div></div></article>`}
function renderFinance(){const box=$('#finance');if(!box)return;const records=accessMembers().flatMap(member=>(member.finance||[]).map(record=>({...record,member,memberId:member.id})));box.innerHTML=`<div class="section-title"><div><p class="eyebrow">FINANCE</p><h2>Financial records</h2></div></div><p class="finance-intro">Store each family member’s accounts and policies in one place.</p><div class="finance-sections">${financeTypes.map(type=>{if(type==='Net Worth Snapshot')return netWorthSnapshot();const items=records.filter(r=>r.type===type||(type==='Loan & EMI Tracker'&&r.type==='Loans'));return `<article class="document-category finance-section"><div class="category-head"><div><h3>${type}</h3></div><b>${items.length}</b></div><div class="category-list">${items.map(r=>`<div class="identity-record"><div><b>Family member: ${r.member.name}</b><small>${financeDetail(r)}</small></div><span class="record-actions"><button onclick="openFinanceModal('${type}','${r.memberId}','${r.id}')">Edit</button><button class="delete" onclick="deleteFinanceRecord('${r.memberId}','${r.id}')">Delete</button></span></div>`).join('')||'<small class="no-docs">No records added yet.</small>'}</div><button class="textbutton" onclick="openFinanceModal('${type}')">+ Add record</button></article>`}).join('')}</div>`}
function renderTrackers(){let box=$('#trackers');if(!box){box=document.createElement('section');box.id='trackers';box.className='document-sections';$('#finance').after(box)}const records=accessMembers().flatMap(member=>(member.finance||[]).map(record=>({...record,member,memberId:member.id})));box.innerHTML=`<div class="section-title"><div><p class="eyebrow">TRACKERS</p><h2>Household trackers</h2></div></div><p class="finance-intro">Track spending, loan commitments, and your household’s recorded value.</p><div class="finance-sections">${trackerTypes.map(type=>{if(type==='Net Worth Snapshot')return netWorthSnapshot();const items=records.filter(record=>record.type===type||(type==='Loan & EMI Tracker'&&record.type==='Loans'));return `<article class="document-category tracker-section"><div class="category-head"><div><h3>${type}</h3></div><b>${items.length}</b></div><div class="category-list">${items.map(record=>`<div class="identity-record"><div><b>Family member: ${record.member.name}</b><small>${financeDetail(record)}</small></div><span class="record-actions"><button onclick="openFinanceModal('${type}','${record.memberId}','${record.id}')">Edit</button><button class="delete" onclick="deleteFinanceRecord('${record.memberId}','${record.id}')">Delete</button></span></div>`).join('')||'<small class="no-docs">No records added yet.</small>'}</div><button class="textbutton" onclick="openFinanceModal('${type}')">+ Add record</button></article>`}).join('')}</div>`}
function financeFields(type,record={}){const memberOptions=state.members.map(m=>`<option value="${m.id}" ${m.id===record.memberId?'selected':''}>${m.name}</option>`).join('');let fields='';if(type==='Expense Tracker')fields=`<label>EXPENSE DATE<input type="date" required name="expenseDate" value="${record.expenseDate||''}"></label><label>CATEGORY<select name="category">${['Utilities','Groceries','Education','Health','Transport','Entertainment','Other'].map(x=>`<option ${record.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>AMOUNT<input required name="amount" value="${record.amount||''}"></label><label>MERCHANT / PAYEE<input name="merchant" value="${record.merchant||''}"></label>`;else if(type==='EPF Account')fields=`<label>UAN NUMBER<input required name="uan" value="${record.uan||''}"></label>`;else if(type==='Insurance policies')fields=`<label>POLICY ID<input required name="policyId" value="${record.policyId||''}"></label><label>POLICY NAME<input required name="policyName" value="${record.policyName||''}"></label><label>MATURITY DATE<input type="date" name="maturityDate" value="${record.maturityDate||''}"></label>`;else if(type==='UPI')fields=`<label>UPI ID<input required name="upiId" value="${record.upiId||''}" placeholder="name@bank"></label><label>UPI APP / PROVIDER<input name="provider" value="${record.provider||''}" placeholder="e.g. GPay"></label><label>LINKED BANK<input name="bankName" value="${record.bankName||''}"></label>`;else if(type==='Loan & EMI Tracker')fields=`<label>LENDER / BANK<input required name="lender" value="${record.lender||''}"></label><label>LOAN ACCOUNT NUMBER<input required name="loanNumber" value="${record.loanNumber||''}"></label><label>LOAN TYPE<input name="loanType" value="${record.loanType||''}" placeholder="e.g. Home loan"></label><label>EMI AMOUNT<input name="emiAmount" value="${record.emiAmount||''}"></label><label>EMI DUE DATE<input type="date" name="emiDueDate" value="${record.emiDueDate||''}"></label><label>OUTSTANDING AMOUNT<input name="outstandingAmount" value="${record.outstandingAmount||''}"></label>`;else if(type==='Fixed Deposits')fields=`<label>BANK NAME<input required name="bankName" value="${record.bankName||''}"></label><label>FD / CERTIFICATE NUMBER<input required name="accountNumber" value="${record.accountNumber||''}"></label><label>MATURITY DATE<input type="date" name="maturityDate" value="${record.maturityDate||''}"></label><label>DEPOSIT AMOUNT<input name="depositAmount" value="${record.depositAmount||''}"></label>`;else if(type==='Credit cards'||type==='Debit cards'||type==='Forex Cards')fields=`<label>${type==='Forex Cards'?'CARD PROVIDER':'BANK NAME'}<input required name="bankName" value="${record.bankName||''}"></label><label>CARD NUMBER<input required name="cardNumber" value="${record.cardNumber||''}"></label><label>CARD NETWORK / CURRENCY<input name="cardNetwork" value="${record.cardNetwork||''}" placeholder="e.g. Visa"></label><label>EXPIRY DATE<input type="date" name="expiryDate" value="${record.expiryDate||''}"></label>`;else fields=`<label>BANK NAME<input required name="bankName" value="${record.bankName||''}"></label><label>ACCOUNT NUMBER<input required name="accountNumber" value="${record.accountNumber||''}"></label>${type==='Banking accounts'?`<label>ACCOUNT TYPE<select name="accountType">${['Savings','Current'].map(x=>`<option ${record.accountType===x?'selected':''}>${x}</option>`).join('')}</select></label>`:''}`;return `<div class="form-grid"><label>FAMILY MEMBER<select required name="member">${memberOptions}</select></label>${fields}</div>`}
function openFinanceModal(type,memberId='',recordId=''){const member=state.members.find(m=>m.id===memberId),record=member?.finance?.find(r=>r.id===recordId)||{};record.memberId=memberId;$('#modalContent').innerHTML=`<h2>${recordId?'Update':'Add'} ${type}</h2><p>Keep this record under the correct family member.</p><form onsubmit="saveFinanceRecord(event,'${type}','${recordId}')">${financeFields(type,record)}<button class="primary">${recordId?'Save changes':'Save record'}</button></form>`;$('#modal').classList.add('show')}
async function saveFinanceRecord(e,type,recordId){e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),memberId=data.member;delete data.member;data.type=type;const response=await fetch(recordId?`/api/members/${memberId}/finance/${recordId}`:`/api/members/${memberId}/finance`,{method:recordId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok){alert('The financial record could not be saved.');return}closeModal();load()}
async function deleteFinanceRecord(memberId,recordId){if(confirm('Delete this financial record?')){await fetch(`/api/members/${memberId}/finance/${recordId}`,{method:'DELETE'});load()}}
function openVehicleModal(id){const v=(state.vehicles||[]).find(x=>x.id===id)||{};$('#modalContent').innerHTML=`<h2>${id?'Update':'Add'} vehicle</h2><p>Keep RC, insurance, PUC, challans, and maintenance scans together.</p><form onsubmit="saveVehicle(event,'${id||''}')"><div class="form-grid"><label>MODEL<input required name="model" value="${v.model||''}" placeholder="e.g. Honda City VX"></label><label>VEHICLE NUMBER<input required name="vehicleNumber" value="${v.vehicleNumber||''}" placeholder="KA 01 AB 1234"></label><label>REGISTRATION DATE<input type="date" name="registrationDate" value="${v.registrationDate||''}"></label><label>REGISTRATION AUTHORITY<input name="registrationAuthority" value="${v.registrationAuthority||''}" placeholder="RTO name"></label><label>ESTIMATED VALUE<input name="estimatedValue" value="${v.estimatedValue||''}" placeholder="e.g. 900000"></label></div><label class="dropzone">↥ &nbsp; Scan RC Book<input name="rcBook" type="file" accept="image/*,.pdf"></label><label class="dropzone">↥ &nbsp; Scan Vehicle Insurance<input name="insurance" type="file" accept="image/*,.pdf"></label><label class="dropzone">↥ &nbsp; Scan Pollution Under Check (PUC)<input name="puc" type="file" accept="image/*,.pdf"></label><label class="dropzone">↥ &nbsp; Scan Challans<input name="challan" type="file" accept="image/*,.pdf"></label><label class="dropzone">↥ &nbsp; Scan Maintenance Service Record<input name="maintenance" type="file" accept="image/*,.pdf"></label><button class="primary">Save vehicle</button></form>`;$('#modal').classList.add('show')}
async function saveVehicle(e,id){e.preventDefault();const form=new FormData(e.target),data=Object.fromEntries(form),readFile=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)}),files={rcBook:['fileName','fileData'],insurance:['insuranceFileName','insuranceFileData'],puc:['pucFileName','pucFileData'],challan:['challanFileName','challanFileData'],maintenance:['maintenanceFileName','maintenanceFileData']};for(const [input,[nameKey,dataKey]] of Object.entries(files)){const file=e.target.querySelector(`input[name=${input}]`).files[0];delete data[input];if(file){data[nameKey]=file.name;data[dataKey]=await readFile(file)}}await fetch(id?`/api/vehicles/${id}`:'/api/vehicles',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});closeModal();load()}
async function deleteVehicle(id){if(confirm('Delete this vehicle record?')){await fetch(`/api/vehicles/${id}`,{method:'DELETE'});load()}}
function activeProperty(){const properties=state.properties||[];return properties.find(p=>p.id===activePropertyId)||properties.at(-1)}
function arrangePropertyLayout(){const section=$('#property'),details=$('#propertyDetails');if(section&&details&&details.parentElement!==section)section.append(details);if(!$('#propertyLayoutStyles')){const style=document.createElement('style');style.id='propertyLayoutStyles';style.textContent='#property{display:grid;grid-template-columns:350px minmax(0,1fr);align-items:start;gap:18px}#property .property-left{grid-column:1 / -1;grid-row:1;text-align:center;justify-self:center;max-width:520px}#property .property-left>p{margin-left:auto;margin-right:auto}#property .property-list{grid-column:1;grid-row:2;width:auto}#property #propertyDetails{grid-column:2;grid-row:2;margin-top:0;min-height:100%}@media(max-width:800px){#property{display:block}#property .property-list{margin-top:15px}#property #propertyDetails{margin-top:15px}}';document.head.append(style)}}
function renderPropertyList(){const box=$('#properties'),properties=state.properties||[];if(!box)return;const selected=activeProperty();box.innerHTML=properties.map(p=>`<article class="property-card ${p.id===selected?.id?'selected':''}" onclick="selectProperty('${p.id}')"><span>⌂</span><div><small>${p.kind||'PROPERTY'}</small><strong>${p.title}</strong><p>${p.address||'No address added'}</p><p>Occupancy: ${p.occupancy||'Not added'}${p.estimatedValue?' · Estimated value: '+formatAmount(amountValue(p.estimatedValue)):''}</p></div><span class="row-actions"><button onclick="event.stopPropagation();openModal('editProperty','${p.id}')">Edit</button><button class="delete" onclick="event.stopPropagation();deleteProperty('${p.id}')">Delete</button></span></article>`).join('')||`<button class="property-card empty-property" onclick="openModal('addProperty')"><span>⌂</span><div><strong>Add your first property</strong><p>Address, owner and property type</p></div><i>→</i></button>`}
function selectProperty(id){activePropertyId=id;renderPropertyList();renderPropertyDetails();showPropertyOwner();showReceiptDates()}
function renderPropertyDetails(){const box=$('#propertyDetails');if(!box)return;const p=activeProperty();if(!p){box.innerHTML='<p class="property-empty">Add a property to manage its documents and appliances.</p>';return}const ownershipDocuments=['Sale deed','Rental Agreement'],utilityDocuments=['Property Tax Receipt','Electricity Bill Receipt','Gas Bill Receipt','Maintenance Bill Receipt','Broadband Bill Receipt','Newspaper Bill Receipt','OTT Subscription / Payment Receipt'],docs=p.documents||[],appliances=p.appliances||[],services=p.services||[],draw=type=>{const d=docs.find(x=>x.type===type);return `<div class="property-row"><span>${type}</span>${d?.fileUrl?`<a href="${d.fileUrl}" target="_blank">${p.title.replace(/\s+/g,'')}_${type.replace(/\s+/g,'')}</a>`:`<button onclick="openPropertyDocument('${p.id}','${type}')">Add scanned copy</button>`}</div>`};box.innerHTML=`<div class="property-detail-head"><b>${p.title}</b><small>${p.address||''}${p.estimatedValue?' · Estimated value: '+formatAmount(amountValue(p.estimatedValue)):''}</small></div><h3>Ownership & tenancy documents</h3>${ownershipDocuments.map(draw).join('')}<h3>Utility Bills & Subscriptions</h3>${utilityDocuments.map(draw).join('')}<div class="appliance-head"><h3>Home appliances</h3><button onclick="openAppliance('${p.id}')">+ Add appliance</button></div>${appliances.map(a=>`<div class="property-row"><span><b>${a.type}</b><small>${a.model||'Model not added'} · Warranty: ${a.warranty||'Not added'}</small></span></div>`).join('')||'<p class="property-empty">Add refrigerator, television, washing machine, water filter, mixer or microwave details.</p>'}<div class="appliance-head"><h3>Home services</h3><button onclick="openPestControl('${p.id}')">+ Add pest control</button></div>${services.map(s=>`<div class="property-row"><span><b>Pest control</b><small>${s.provider||'Provider not added'} · Last service: ${s.serviceDate||'Not added'} · Next due: ${s.nextDueDate||'Not added'}${s.contact?' · '+s.contact:''}</small></span>${s.fileUrl?`<a href="${s.fileUrl}" target="_blank">${p.title.replace(/\s+/g,'')}_PestControlReceipt</a>`:''}</div>`).join('')||'<p class="property-empty">Add a pest-control service to track the provider and next treatment date.</p>'}`}
function showPropertyOwner(){const p=activeProperty(),head=$('#propertyDetails .property-detail-head');if(!p||!head)return;const owner=document.createElement('small'),occupancy=document.createElement('small');owner.textContent=`Owner${(p.owners||[]).length>1?'s':''}: ${p.owner||'Not added'}`;occupancy.textContent=`Occupancy: ${p.occupancy||'Not added'}`;head.append(owner,occupancy)}
function showPropertyOccupancyRight(){}
function showReceiptDates(){const p=activeProperty(),box=$('#propertyDetails');if(!p||!box)return;const types=['Sale deed','Rental Agreement','Property Tax Receipt','Electricity Bill Receipt','Gas Bill Receipt','Maintenance Bill Receipt','Broadband Bill Receipt','Newspaper Bill Receipt','OTT Subscription / Payment Receipt'];types.forEach((type,index)=>{const d=(p.documents||[]).find(x=>x.type===type);if(!d?.fileUrl)return;const label=document.createElement('small');label.className='receipt-date';label.textContent=`Document date: ${d.documentDate||'Not detected — review scan'}`;box.querySelectorAll('.property-row')[index]?.querySelector('span')?.append(label)})}
function openPropertyDocument(propertyId,type){$('#modalContent').innerHTML=`<h2>${type}</h2><p>Upload the scanned copy for this property.</p><form onsubmit="savePropertyDocument(event,'${propertyId}','${type}')"><label class="dropzone">↥ &nbsp; Choose a scan or PDF<input type="file" required accept="image/*,.pdf"></label><button class="primary">Save scanned copy</button></form>`;$('#modal').classList.add('show')}
async function savePropertyDocument(e,propertyId,type){e.preventDefault();const file=e.target.querySelector('input[type=file]').files[0];if(!file){alert('Choose a scan or PDF first.');return}const fileData=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)}),response=await fetch(`/api/properties/${propertyId}/documents`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,fileName:file.name,fileData})});if(!response.ok){alert('The scanned copy could not be saved. Please restart the server and try again.');return}const saved=await response.json();if(!saved.fileUrl){alert('The file was received but could not be linked to this property. Please try again.');return}activePropertyId=propertyId;closeModal();load()}
function openAppliance(propertyId){const types=['Refrigerator','Television','Washing machine','Water Filter','Mixer','Microwave oven'];$('#modalContent').innerHTML=`<h2>Add home appliance</h2><p>Store warranty and support details with this property.</p><form onsubmit="saveAppliance(event,'${propertyId}')"><div class="form-grid"><label>APPLIANCE<select name="type">${types.map(x=>`<option>${x}</option>`).join('')}</select></label><label>MODEL<input name="model" required></label><label>MANUFACTURER<input name="manufacturer"></label><label>WARRANTY DATE<input name="warranty" type="date"></label><label>AMC DETAILS<input name="amc"></label><label>SUPPORT CONTACT<input name="support"></label><label class="full">SPECIFICATION<input name="specification"></label></div><button class="primary">Save appliance</button></form>`;$('#modal').classList.add('show')}
async function saveAppliance(e,propertyId){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));await fetch(`/api/properties/${propertyId}/appliances`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});closeModal();load()}
function openPestControl(propertyId){$('#modalContent').innerHTML=`<h2>Add pest control service</h2><p>Record the provider, service schedule, contact, and optional receipt.</p><form onsubmit="savePestControl(event,'${propertyId}')"><div class="form-grid"><label>PROVIDER<input required name="provider"></label><label>CONTACT<input name="contact"></label><label>SERVICE DATE<input required type="date" name="serviceDate"></label><label>NEXT DUE DATE<input type="date" name="nextDueDate"></label><label class="full">NOTES<input name="notes" placeholder="Treatment, coverage or instructions"></label></div><label class="dropzone">↥ &nbsp; Upload receipt or service report (optional)<input type="file" accept="image/*,.pdf"></label><button class="primary">Save pest control service</button></form>`;$('#modal').classList.add('show')}
async function savePestControl(e,propertyId){e.preventDefault();const form=new FormData(e.target),file=e.target.querySelector('input[type=file]').files[0],data=Object.fromEntries(form);if(file){data.fileName=file.name;data.fileData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}const response=await fetch(`/api/properties/${propertyId}/services`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok){alert('The pest-control service could not be saved.');return}activePropertyId=propertyId;closeModal();load()}
function showMetadata(){const identity=['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate'],education=['Class 10','Class 12','Graduation','Post Graduation','PhD','Achievement'],docs=accessMembers().flatMap(m=>m.documents.map(d=>({...d,member:m.name,memberId:m.id}))),fieldNames={Aadhaar:'Aadhaar number',Passport:'Passport number','Voter ID':'Voter ID number','PAN Card':'PAN number','Driving Licence':'Licence number','Birth Certificate':'Certificate reference','Marriage Certificate':'Certificate reference'},record=d=>`<div class="identity-record"><div><b>Family member: ${d.member}</b><small>${fieldNames[d.type]||'Reference'}: ${d.number||'Not added'} · Name: ${d.documentName||'Not added'}${d.documentDate?' · DOB / date: '+d.documentDate:''}${d.expiry?' · Expiry: '+d.expiry:''}${d.issuer?' · RTO / authority: '+d.issuer:''}</small>${d.address?`<p class="address">⌖ Address: ${d.address}</p>`:''}</div><span class="record-actions">${d.fileUrl?`<a href="${d.fileUrl}" target="_blank">Open scan</a>`:'<small>Scan not attached</small>'}<button onclick="openModal('editDoc','${d.memberId}','${d.id}')">Edit</button><button class="delete" onclick="deleteDoc('${d.memberId}','${d.id}')">Delete</button></span></div>`,educationRecord=d=>`<div class="identity-record"><div><b>Family member: ${d.member} · ${d.type}</b><small>Name: ${d.documentName||'Not added'}${d.documentDate?' · Passout date: '+d.documentDate:''}${d.number?' · Reference: '+d.number:''}</small></div><span class="record-actions">${d.fileUrl?`<a href="${d.fileUrl}" target="_blank">Open scan</a>`:'<small>Scan not attached</small>'}<button onclick="openModal('editDoc','${d.memberId}','${d.id}')">Edit</button><button class="delete" onclick="deleteDoc('${d.memberId}','${d.id}')">Delete</button></span></div>`;$('#identityDocs').innerHTML=identity.map(type=>{const items=docs.filter(d=>d.type===type);return `<section class="identity-type"><h4>${type}</h4><p>${items.length?items.map(record).join(''):'No record added yet.'}</p></section>`}).join('');const eds=docs.filter(d=>education.includes(d.type));$('#educationDocs').innerHTML=eds.map(educationRecord).join('')||'<small class="no-docs">Nothing added yet</small>'}

const identityTypes=['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate'];
const identityIcons={Aadhaar:'fingerprint',Passport:'public','Voter ID':'how_to_vote','PAN Card':'credit_card','Driving Licence':'directions_car','Birth Certificate':'child_care','Marriage Certificate':'favorite'};
let identityFilter='All documents';
function identityDocuments(){return accessMembers().flatMap(member=>(member.documents||[]).filter(document=>identityTypes.includes(document.type)).map(document=>({...document,member:member.name,memberId:member.id})))}
function identityDate(value){if(!value)return '';const date=new Date(value+'T00:00:00');return Number.isNaN(date.getTime())?value:date.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}
function openIdentityUpload(type=''){openModal('upload','identity');const select=$('#modalContent [name="type"]');if(select&&type)select.value=type}
function renderIdentityWorkspace(){const section=$('#identification');if(!section)return;const docs=identityDocuments(),members=accessMembers(),detailType=identityFilter==='All documents'?'':identityFilter,detailDocs=detailType?docs.filter(document=>document.type===detailType):[];section.innerHTML=`<div class="identity-page-head"><div><p class="eyebrow">IDENTITY &amp; DOCUMENTS</p><h2>${detailType||'Your family documents'}</h2><p>${detailType?`View and manage saved ${detailType} records for your family.`:'See which identity records are available for every family member.'}</p></div><button class="identity-add" onclick="openIdentityUpload('${detailType}')"><span>+</span> Add ${detailType||'document'}</button></div><div class="identity-toolbar"><label class="identity-search"><span class="material-symbols-rounded">search</span><input id="identitySearch" placeholder="Search family members" oninput="filterIdentityRecords()"></label><div class="identity-view-label"><span class="material-symbols-rounded">lock</span> Private to your household</div></div>${detailType?`<div id="identityDocs" class="identity-detail-list">${detailDocs.map(identityDetailRow).join('')}</div>`:`<div id="identityDocs" class="identity-table-wrap"><table class="identity-table"><thead><tr><th>Family member</th>${identityTypes.map(type=>`<th data-type="${type}">${type}</th>`).join('')}</tr></thead><tbody>${members.map(member=>identityTableRow(member,docs)).join('')}</tbody></table></div>`}<div id="identityEmpty" class="identity-empty" ${detailType&&detailDocs.length===0?'':'hidden'}><span class="material-symbols-rounded">${detailType?'description':'person_search'}</span><h3>${detailType?`No ${detailType} documents`:'No family members found'}</h3><p>${detailType?'Add the first document for a family member.':'Try another search.'}</p>${detailType?`<button onclick="openIdentityUpload('${detailType}')">Add ${detailType}</button>`:''}</div>`;filterIdentityRecords()}
function identityDetailRow(document){const fields=[['Name on document',document.documentName],['Document number',document.number],['Date of birth / date',identityDate(document.documentDate)],['Address',document.address],['Expiry date',identityDate(document.expiry)],['Issuing authority',document.issuer]],verified=document.status==='Verified';return `<article class="identity-detail-row" data-search="${`${document.member} ${document.documentName||''} ${document.number||''} ${document.address||''}`.toLowerCase()}"><div class="identity-detail-heading"><span class="identity-member-avatar">${initials(document.member)}</span><div><small>Family member</small><h3>${document.member}</h3></div><span class="identity-status ${verified?'verified':'review'}"><i></i>${verified?'Verified':'Review needed'}</span></div><dl class="identity-metadata">${fields.map(([label,value])=>`<div class="${label==='Address'?'wide':''}"><dt>${label}</dt><dd>${value||'Not added'}</dd></div>`).join('')}</dl><div class="identity-detail-actions record-actions">${document.fileUrl?`<a href="${document.fileUrl}" target="_blank"><span class="material-symbols-rounded">visibility</span> View scan</a><button onclick="rereadDoc('${document.memberId}','${document.id}')"><span class="material-symbols-rounded">document_scanner</span> Re-read</button>`:'<span class="scan-missing">Scan not attached</span>'}<button onclick="openModal('editDoc','${document.memberId}','${document.id}')"><span class="material-symbols-rounded">edit</span> Edit details</button>${verified?'':`<button class="verify-document" onclick="verifyIdentityDocument('${document.memberId}','${document.id}',this)"><span class="material-symbols-rounded">verified</span> Mark as verified</button>`}<button class="delete" onclick="deleteIdentityDocument('${document.memberId}','${document.id}')"><span class="material-symbols-rounded">delete</span> Delete</button></div></article>`}
async function deleteIdentityDocument(memberId,documentId){if(!confirm('Delete this document record and its saved scan?'))return;const currentType=identityFilter,response=await fetch(`/api/members/${memberId}/documents/${documentId}`,{method:'DELETE'});if(!response.ok){alert('The document could not be deleted. Please try again.');return}const owner=state.members.find(member=>member.id===memberId);if(owner)owner.documents=owner.documents.filter(document=>document.id!==documentId);renderIdentityWorkspace();setIdentityType(currentType)}
async function verifyIdentityDocument(memberId,documentId,button){if(button){button.disabled=true;button.innerHTML='<span class="material-symbols-rounded">progress_activity</span> Verifying…'}try{const response=await fetch(`/api/members/${memberId}/documents/${documentId}`,{method:'PUT',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({status:'Verified'})}),result=await response.json();if(!response.ok)throw new Error(result.error||'The document could not be verified.');const document=state.members.find(member=>member.id===memberId)?.documents.find(item=>item.id===documentId);if(document)document.status=result.status||'Verified';renderIdentityWorkspace();document.querySelectorAll('.identity-submenu button').forEach(item=>{const active=item.textContent===identityFilter;item.classList.toggle('active',active);item.style.background=active?'#eceaff':'transparent'})}catch(error){if(button){button.disabled=false;button.innerHTML='<span class="material-symbols-rounded">verified</span> Mark as verified'}alert(error.message||'The document could not be verified. Please try again.')}}
function identityTableRow(member,docs){return `<tr data-search="${`${member.name} ${member.relation||''}`.toLowerCase()}"><th><span class="identity-member-avatar">${initials(member.name)}</span><span><b>${member.name}</b><small>${member.relation||'Family member'}</small></span></th>${identityTypes.map(type=>{const present=docs.some(item=>item.memberId===member.id&&item.type===type);return `<td data-type="${type}"><span class="document-presence ${present?'present':'absent'}" role="img" aria-label="${present?'Present':'Absent'}"><span class="material-symbols-rounded">${present?'check':'close'}</span></span></td>`}).join('')}</tr>`}
function identityCard(document){const status=document.status==='Verified'?'Verified':'Review needed',meta=[document.number?`No. ${document.number}`:'Number not added',document.documentDate?`DOB / date ${identityDate(document.documentDate)}`:'Date not added'];return `<article class="identity-card" data-type="${document.type}" data-search="${`${document.type} ${document.member} ${document.documentName||''} ${document.number||''}`.toLowerCase()}"><div class="identity-card-top"><span class="identity-doc-icon material-symbols-rounded">${identityIcons[document.type]||'description'}</span><span class="identity-status ${status==='Verified'?'verified':'review'}"><i></i>${status}</span><button class="identity-more" aria-label="Edit ${document.type}" onclick="openModal('editDoc','${document.memberId}','${document.id}')">⋯</button></div><div class="identity-card-body"><small>${document.type}</small><h3>${document.documentName||document.member}</h3><p><span class="member-dot">${initials(document.member)}</span>${document.member}</p><dl><div><dt>Document details</dt><dd>${meta.join(' · ')}</dd></div>${document.expiry?`<div><dt>Expiry</dt><dd>${identityDate(document.expiry)}</dd></div>`:''}</dl></div></article>`}
function filterIdentityRecords(){const query=($('#identitySearch')?.value||'').trim().toLowerCase(),items=[...document.querySelectorAll('#identityDocs tbody tr,#identityDocs .identity-detail-row')];let visible=0;items.forEach(item=>{const show=!query||item.dataset.search.includes(query);item.hidden=!show;if(show)visible+=1});const empty=$('#identityEmpty');if(empty)empty.hidden=visible!==0}
function render(){const members=accessMembers(),docs=members.flatMap(m=>m.documents.map(d=>({...d,member:m.name,memberId:m.id})));$('#memberCount').textContent=members.length;$('#docCount').textContent=docs.length;$('#verifiedCount').textContent=docs.filter(d=>d.status==='Verified').length;$('#healthCount').textContent=0;
$('#members').innerHTML=members.map((m,i)=>`<article class="member"><div class="card-actions"><button onclick="openModal('editMember','${m.id}')">Edit</button><button class="delete" onclick="deleteMember('${m.id}')">Delete</button></div><div class="member-top"><span class="avatar" style="background:${colors[i%4]}">${initials(m.name)}</span><h3>${m.name}<small>${m.relation||'Family member'}</small></h3></div><div class="member-info"><span>DATE OF BIRTH<b>${m.dob?new Date(m.dob+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not added'}</b></span><span>BLOOD GROUP<b>${m.bloodGroup||'—'}</b></span><span>RECORDS<b>${m.documents.length} stored</b></span></div></article>`).join('')||`<div class="empty"><b>Your family vault is ready.</b><span>Add your first family member to start organising records.</span><button class="primary" onclick="openModal('addMember')">+ Add member</button></div>`;
$('#activity').innerHTML=docs.slice().reverse().slice(0,3).map(d=>`<div class="activity"><span class="doc-icon">▤</span><span><b>${d.type} · ${d.member}</b><small>${d.uploadedAt||'Recently added'} · ${d.number||'Document stored'}</small></span><em>${d.status||'Review needed'}</em><span class="row-actions">${d.fileUrl?`<a href="${d.fileUrl}" target="_blank">Open</a>`:''}<button onclick="openModal('editDoc','${d.memberId}','${d.id}')">Edit</button><button class="delete" onclick="deleteDoc('${d.memberId}','${d.id}')">Delete</button></span></div>`).join('')||'<p class="sub">No documents yet — upload one to get started.</p>';const identity=['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate'],education=['Class 10','Class 12','Graduation','Post Graduation','PhD','Achievement'];const draw=(list,id)=>$(id).innerHTML=list.map(d=>`<div><span>${d.type}</span><small>${d.member}</small>${d.fileUrl?`<a href="${d.fileUrl}" target="_blank">Open scan</a>`:''}</div>`).join('')||'<small class="no-docs">Nothing added yet</small>';const ids=docs.filter(d=>identity.includes(d.type)),eds=docs.filter(d=>education.includes(d.type));$('#identityCount').textContent=ids.length;$('#educationCount').textContent=eds.length;draw(ids,'#identityDocs');draw(eds,'#educationDocs');$('#properties').innerHTML=(state.properties||[]).map(p=>`<div class="property-card"><span>⌂</span><div><small>${p.kind||'PROPERTY'}</small><strong>${p.title}</strong><p>${p.address||'No address added'}${p.owner?' · Owner: '+p.owner:''}</p></div><span class="row-actions"><button onclick="openModal('editProperty','${p.id}')">Edit</button><button class="delete" onclick="deleteProperty('${p.id}')">Delete</button></span></div>`).join('')||`<button class="property-card empty-property" onclick="openModal('addProperty')"><span>⌂</span><div><strong>Add your first property</strong><p>Address, owner and property type</p></div><i>→</i></button>`}
function fields(m={}){return `<div class="form-grid"><label class="full">FULL NAME<input required name="name" value="${m.name||''}"></label><label>RELATION<select name="relation">${['Self','Spouse','Child','Parent','Other'].map(x=>`<option ${m.relation===x?'selected':''}>${x}</option>`).join('')}</select></label><label>GENDER<select name="gender">${['Female','Male','Other'].map(x=>`<option ${m.gender===x?'selected':''}>${x}</option>`).join('')}</select></label><label>BLOOD GROUP<select name="bloodGroup">${['Unknown','A+','A-','B+','B-','AB+','AB-','O+','O-'].map(x=>`<option ${m.bloodGroup===x?'selected':''}>${x}</option>`).join('')}</select></label></div>`}
function docFields(d={},category){const types=category==='identity'?['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate']:category==='education'?['Class 10','Class 12','Graduation','Post Graduation','PhD']:['Aadhaar','Passport','Voter ID','PAN Card','Driving Licence','Birth Certificate','Marriage Certificate','Class 10','Class 12','Graduation','Post Graduation','PhD','Achievement','Health Report','Insurance Policy'];const education=category==='education';return `${education?`<label>EDUCATION<select name="type">${types.map(x=>`<option ${d.type===x?'selected':''}>${x}</option>`).join('')}</select></label>`:`<label>DOCUMENT TYPE<select name="type">${types.map(x=>`<option ${d.type===x?'selected':''}>${x}</option>`).join('')}</select></label>`}<label>NAME ON DOCUMENT<input name="documentName" value="${d.documentName||''}" placeholder="Name as printed"></label><label>${education?'YEAR OF PASSING':'DATE OF BIRTH'}<input ${education?'type="number" min="1900" max="2100"':'type="date"'} name="documentDate" value="${d.documentDate||''}" placeholder="e.g. 2024"></label>${education?`<label>DOCUMENT TYPE<select name="subtype">${['Certificate','Marksheet'].map(x=>`<option ${d.subtype===x?'selected':''}>${x}</option>`).join('')}</select></label>`:`<label>EXPIRY DATE (IF APPLICABLE)<input type="date" name="expiry" value="${d.expiry||''}"></label><label>DOCUMENT NUMBER / REFERENCE<input name="number" value="${d.number||''}" placeholder="Document number"></label><label>RTO / ISSUING AUTHORITY<input name="issuer" value="${d.issuer||''}" placeholder="Required for driving licence"></label><label class="full">ADDRESS ON DOCUMENT<textarea name="address" placeholder="Address as printed">${d.address||''}</textarea></label>`}<label class="full">SCAN OR DOCUMENT FILE<input type="file" accept="image/*,.pdf"></label>`}
function propertyFields(p={}){const owners=Array.isArray(p.owners)?p.owners:(p.owner||'').split(',').map(x=>x.trim()).filter(Boolean);return `<div class="form-grid"><label class="full">PROPERTY NAME<input required name="title" value="${p.title||''}" placeholder="e.g. Green Acres Apartment"></label><label>PROPERTY TYPE<select name="kind">${['Apartment','Independent house','Plot','Commercial'].map(x=>`<option ${p.kind===x?'selected':''}>${x}</option>`).join('')}</select></label><label>OCCUPANCY<select name="occupancy">${['Residing','Rented out'].map(x=>`<option ${p.occupancy===x?'selected':''}>${x}</option>`).join('')}</select></label><label>ESTIMATED VALUE<input name="estimatedValue" value="${p.estimatedValue||''}" placeholder="e.g. 8500000"></label><label>OWNERS <small>(select one or more)</small><select name="owners" multiple size="4">${state.members.map(m=>`<option value="${m.name}" ${owners.includes(m.name)?'selected':''}>${m.name}</option>`).join('')}</select></label><label class="full">ADDRESS<input name="address" value="${p.address||''}" placeholder="Full property address"></label></div>`}
function openModal(kind,mid,did){const c=$('#modalContent'),m=state.members.find(x=>x.id===mid),p=(state.properties||[]).find(x=>x.id===mid);if(kind==='addMember')c.innerHTML=`<h2>Add a family member</h2><p>Create a profile to keep their records organised.</p><form onsubmit="saveMember(event)">${fields()}<button class="primary">Create profile</button></form>`;else if(kind==='editMember')c.innerHTML=`<h2>Update ${m.name}</h2><p>Changes are saved to your household vault.</p><form onsubmit="saveMember(event,'${m.id}')">${fields(m)}<button class="primary">Save changes</button></form>`;else if(kind==='addProperty'||kind==='editProperty')c.innerHTML=`<h2>${kind==='addProperty'?'Add a property':'Update '+p.title}</h2><p>Keep ownership and address details in one place.</p><form onsubmit="saveProperty(event,'${p?.id||''}')">${propertyFields(p)}<button class="primary">${kind==='addProperty'?'Add property':'Save changes'}</button></form>`;else if(kind==='editDoc'){const d=m.documents.find(x=>x.id===did);c.innerHTML=`<h2>Update document</h2><p>Review or correct the captured details.</p><form onsubmit="saveDoc(event,'${m.id}','${d.id}')"><div class="form-grid">${docFields(d)}</div><button class="primary">Save changes</button></form>`}else{const category=['identity','education'].includes(mid)?mid:undefined;c.innerHTML=`<h2>Upload a document</h2><p>We’ll read the document and populate its details for you.</p><form onsubmit="saveDoc(event)"><div class="form-grid"><label>FAMILY MEMBER<select required name="member">${state.members.map(m=>`<option value="${m.id}">${m.name}</option>`).join('')}</select></label>${docFields({},category)}</div><label class="dropzone">↥ &nbsp; Choose a scan or photo<input type="file"></label><button class="primary">Upload & extract details</button></form>`}$('#modal').classList.add('show')}
function closeModal(){$('#modal').classList.remove('show')}
async function saveMember(e,id){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));await fetch(id?'/api/members/'+id:'/api/members',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});closeModal();load()}
function showIntakeProgress(form,message,detail=''){let status=form.querySelector('.agent-intake-progress');if(!status){status=document.createElement('div');status.className='agent-intake-progress';status.setAttribute('role','status');status.setAttribute('aria-live','polite');form.prepend(status)}status.innerHTML=`<b>${message}</b>${detail?`<small>${detail}</small>`:''}`}
function applyIntakeToDocumentForm(form,intake){const metadata=intake.metadata||{},set=(name,value)=>{const field=form.querySelector(`[name="${name}"]`);if(field&&value)field.value=value};set('type',intake.documentType);set('number',metadata.number);set('documentName',metadata.documentName);set('documentDate',metadata.documentDate);set('expiry',metadata.expiry);set('issuer',metadata.issuer);set('address',metadata.address);const member=form.querySelector('[name="member"]');if(member){if(intake.memberId&&intake.confidence>=.7)member.value=intake.memberId;else{if(!member.querySelector('option[value=""]'))member.insertAdjacentHTML('afterbegin','<option value="">Select the correct family member</option>');member.value=''}}form.dataset.intake=JSON.stringify(intake);form.dataset.intakeReady='true';let review=form.querySelector('.agent-intake-review');if(!review){review=document.createElement('div');review.className='agent-intake-review';form.prepend(review)}const memberName=state.members.find(item=>item.id===intake.memberId)?.name||'No confident family-member match';review.innerHTML=`<b>Document intake review</b><small>Suggested type: ${intake.documentType||'Other'} · Suggested member: ${memberName} · Confidence: ${Math.round((intake.confidence||0)*100)}%</small><small>${intake.reviewNote||'Review the filled fields before saving.'}</small>${(intake.missingFields||[]).length?`<small>Needs attention: ${intake.missingFields.join(', ')}</small>`:''}`;const submit=form.querySelector('button.primary');if(submit)submit.textContent='Save reviewed document';showIntakeProgress(form,'Extraction complete — review the fields, then save the document.','Nothing has been stored yet.')}
async function saveDoc(e,mid,did){e.preventDefault();const form=e.target;if(form.dataset.submitting==='true')return;form.dataset.submitting='true';const f=new FormData(form),file=[...form.querySelectorAll('input[type=file]')].map(x=>x.files[0]).find(Boolean),toData=()=>({type:new FormData(form).get('type'),subtype:new FormData(form).get('subtype')||'',number:new FormData(form).get('number')||'',documentName:new FormData(form).get('documentName')||'',documentDate:new FormData(form).get('documentDate')||'',expiry:new FormData(form).get('expiry')||'',issuer:new FormData(form).get('issuer')||'',address:new FormData(form).get('address')||''});let member=mid||f.get('member'),data=toData();if(file){data.fileName=file.name;data.fileData=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});if(!form.dataset.intakeReady){const submit=form.querySelector('button.primary');if(submit){submit.textContent='Extracting details…';submit.disabled=true}showIntakeProgress(form,'Reading your scan locally…','OCR is extracting text from the PDF or image.');try{const progressTimer=setTimeout(()=>showIntakeProgress(form,'Analysing extracted text privately…','Matching the document type, member, and metadata.'),1800),intakeResponse=await fetch('/api/agent/document-intake',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileName:file.name,fileData:data.fileData})});clearTimeout(progressTimer);const intake=await intakeResponse.json();if(!intakeResponse.ok)throw new Error(intake.error||'The intake agent could not read this scan.');applyIntakeToDocumentForm(form,intake)}catch(error){showIntakeProgress(form,'Could not extract details.',error.message||'Please try again with a clearer scan.')}finally{form.dataset.submitting='false';if(submit){submit.disabled=false;if(!form.dataset.intakeReady)submit.textContent='Upload & extract details'}}return}data.agentIntake=JSON.parse(form.dataset.intake||'{}');if(!mid&&form.querySelector('[name="member"]'))member=form.querySelector('[name="member"]').value}const submit=form.querySelector('button.primary');if(submit){submit.disabled=true;submit.textContent=did?'Saving changes…':'Saving document…'}const response=await fetch(did?`/api/members/${member}/documents/${did}`:`/api/members/${member}/documents`,{method:did?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok){form.dataset.submitting='false';if(submit){submit.disabled=false;submit.textContent=did?'Save changes':'Save reviewed document'}alert('The file could not be saved. Please try again.');return}closeModal();await load()}
async function saveProperty(e,id){e.preventDefault();const form=new FormData(e.target),data=Object.fromEntries(form),owners=form.getAll('owners');data.owners=owners;data.owner=owners.join(', ');const response=await fetch(id?'/api/properties/'+id:'/api/properties',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const property=await response.json();activePropertyId=property.id;closeModal();load()}async function deleteProperty(id){if(confirm('Delete this property?')){await fetch('/api/properties/'+id,{method:'DELETE'});if(activePropertyId===id)activePropertyId=undefined;load()}}async function deleteMember(id){if(confirm('Delete this family member and all their documents?')){await fetch(`/api/members/${id}`,{method:'DELETE'});load()}}async function deleteDoc(m,id){if(confirm('Delete this document?')){await fetch(`/api/members/${m}/documents/${id}`,{method:'DELETE'});load()}}$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});document.addEventListener('click',e=>{const link=e.target.closest('a[href^="/api/files/"]');if(!link)return;e.preventDefault();window.open(link.href,'_blank','noopener')});window.addEventListener('hashchange',applyDocumentView);load();
